import type { NavVisibilityInput } from './appNavigation';

export const getNavUnlockHints = (input: NavVisibilityInput): string[] => {
  const hints: string[] = [];
  if (!input.hasProfile) {
    return ['Complete company registration to unlock the full workspace menu.'];
  }
  if (!input.hasAssessment) {
    hints.push('Run a carbon assessment to unlock Carbon offsets & credits and carbon forecasting.');
  }
  if (input.hasProfile && input.hasAssessment && input.hasExportIntent !== true) {
    hints.push('Set export intent in Compliance Hub to unlock CBAM and export compliance tracks.');
  }
  return hints;
};
