import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { complianceSectionHref } from '../../constants/complianceHub';
import ApiService from '../../services/api';
import { getStoredSignupGoal } from '../../constants/signupGoals';

interface BuyerInboxItem {
  buyerName: string;
  frameworkLabel: string;
  urgency: string;
  daysToDue: number | null;
  dueDate?: string | null;
  readinessScore?: number;
  packReady?: boolean;
  missingPackFields?: string[];
  missingQuestionnaireFields?: string[];
  packHubLink?: string;
}

const urgencyColor = (urgency: string): 'error' | 'warning' | 'default' => {
  if (urgency === 'high' || urgency === 'overdue') return 'error';
  if (urgency === 'medium') return 'warning';
  return 'default';
};

const BuyerRequestInbox: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [inbox, setInbox] = useState<BuyerInboxItem[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.runMsmeAdvisory({
        signupGoal: getStoredSignupGoal() || 'buyer_audit',
        period: 'annual',
      });
      const data = (res as { data?: { outputs?: { buyerAdvisory?: { inbox?: BuyerInboxItem[] } } } })?.data;
      setInbox(data?.outputs?.buyerAdvisory?.inbox || []);
    } catch (e) {
      setInbox([]);
      setError(e instanceof Error ? e.message : 'Could not load buyer request inbox');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  if (error) {
    return <Alert severity="warning">{error}</Alert>;
  }

  if (inbox.length === 0) {
    return (
      <Alert severity="info">
        No open buyer questionnaires. When a customer sends a sustainability audit template, register it in
        Compliance hub supplier questionnaires.
      </Alert>
    );
  }

  return (
    <Stack spacing={2}>
      {inbox.map((item) => (
        <Card key={`${item.buyerName}-${item.dueDate || 'nodate'}`} variant="outlined">
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
              <Box>
                <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                  {item.buyerName}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {item.frameworkLabel}
                </Typography>
                {item.daysToDue != null ? (
                  <Typography variant="caption" color="text.secondary">
                    {item.daysToDue < 0
                      ? `${Math.abs(item.daysToDue)} day(s) overdue`
                      : `Due in ${item.daysToDue} day(s)`}
                  </Typography>
                ) : null}
                {item.readinessScore != null ? (
                  <Typography variant="caption" color="text.secondary" display="block">
                    {item.readinessScore}% ready
                    {!item.packReady ? ' · pack gaps remain' : ' · pack valid'}
                  </Typography>
                ) : null}
              </Box>
              <Chip size="small" label={item.urgency} color={urgencyColor(item.urgency)} />
            </Stack>
            {(item.missingPackFields?.length || item.missingQuestionnaireFields?.length) ? (
              <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                Missing:{' '}
                {[
                  ...(item.missingQuestionnaireFields || []).slice(0, 2),
                  ...(item.missingPackFields || []).slice(0, 2),
                ].join(', ')}
              </Typography>
            ) : null}
            <Button
              component={RouterLink}
              to={item.packHubLink || complianceSectionHref('/compliance/export', 'supplier-portal')}
              size="small"
              sx={{ mt: 1.5 }}
            >
              Complete buyer pack
            </Button>
          </CardContent>
        </Card>
      ))}
    </Stack>
  );
};

export default BuyerRequestInbox;
