import { useCallback, useEffect, useState } from 'react';
import apiService from '../services/api';
import { FALLBACK_PUBLIC_PRICING, PublicPricingData } from '../constants/pricingPlans';

interface PublicPricingVisibility {
  pricingVisible: boolean;
  loading: boolean;
  refresh: () => Promise<void>;
}

export function usePublicPricingVisibility(): PublicPricingVisibility {
  const [pricingVisible, setPricingVisible] = useState(false);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    try {
      setLoading(true);
      const response = (await apiService.getPublicPricingPlans()) as {
        success?: boolean;
        data?: PublicPricingData;
      };
      const moduleEnabled =
        response?.success && response.data
          ? response.data.moduleEnabled === true
          : FALLBACK_PUBLIC_PRICING.moduleEnabled === true;
      setPricingVisible(moduleEnabled);
    } catch {
      setPricingVisible(FALLBACK_PUBLIC_PRICING.moduleEnabled === true);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return { pricingVisible, loading, refresh };
}
